class Inventory {
  #counts = new Map();

  static from(obj) {
    const inv = new Inventory();
    for (const [name, count] of Object.entries(obj)) inv.add(name, count);
    return inv;
  }

  #checkCount(count) {
    if (!Number.isInteger(count) || count <= 0) throw new RangeError("count must be a positive whole number");
  }

  add(name, count = 1) {
    this.#checkCount(count);
    this.#counts.set(name, this.count(name) + count);
    return this;
  }

  remove(name, count = 1) {
    this.#checkCount(count);
    const have = this.count(name);
    if (have < count) return false;
    if (have === count) this.#counts.delete(name);
    else this.#counts.set(name, have - count);
    return true;
  }

  count(name) {
    return this.#counts.get(name) ?? 0;
  }

  get total() {
    let sum = 0;
    for (const n of this.#counts.values()) sum += n;
    return sum;
  }

  names() {
    return [...this.#counts.keys()].sort();
  }
}

class LimitedInventory extends Inventory {
  #max;
  constructor(max) {
    super();
    this.#max = max;
  }
  add(name, count = 1) {
    if (Number.isInteger(count) && count > 0 && this.total + count > this.#max) throw new RangeError("full");
    return super.add(name, count);
  }
}

unitTests:
test("adding, removing and counting", () => {
  const inv = new Inventory();
  check(inv.add("apple", 3).add("pear").add("apple", 2) === inv, "add should return this");
  checkEq(inv.count("apple"), 5);
  checkEq(inv.remove("apple", 4), true);
  checkEq(inv.remove("apple", 4), false);
  checkEq(inv.count("apple"), 1);
  checkEq(inv.count("plum"), 0);
  checkEq(inv.total, 2);
  checkEq(inv.names(), ["apple", "pear"]);
  inv.remove("pear");
  checkEq(inv.names(), ["apple"]);
});

test("state is private", () => {
  const inv = new Inventory().add("x", 2);
  checkEq(Object.keys(inv), []);
  checkEq(JSON.stringify(inv), "{}");
});

test("bad counts throw RangeError", () => {
  const inv = new Inventory();
  checkThrows(() => inv.add("x", 0), RangeError);
  checkThrows(() => inv.add("x", 1.5), RangeError);
  checkThrows(() => inv.remove("x", -1), RangeError);
});

test("static factory", () => {
  const inv = Inventory.from({ tea: 2, cake: 1 });
  check(inv instanceof Inventory, "from should build an Inventory");
  checkEq([inv.count("tea"), inv.count("cake"), inv.total], [2, 1, 3]);
});

test("subclass with a limit", () => {
  const lim = new LimitedInventory(3);
  lim.add("a", 2).add("b");
  checkEq(lim.total, 3);
  checkThrows(() => lim.add("c"), RangeError);
  checkEq(lim.count("c"), 0);
  lim.remove("a");
  lim.add("c");
  checkEq(lim.names(), ["a", "b", "c"]);
  check(lim instanceof Inventory, "LimitedInventory should extend Inventory");
});

